Method.Source:
/// <summary>
/// Finds a barcode with weight specification.
/// </summary>
/// <param name="itemBarCode">The item barcode.</param>
/// <param name="barcodeSetupId">The barcode setup ID.</param>
/// <param name="_selectForUpdate">Indicates if the record should be selected for update.</param>
/// <returns>The InventItemBarcode record.</returns>
public static InventItemBarcode findBarcode_AVA(ItemBarCode itemBarCode, BarcodeSetupId barcodeSetupId = AVAConstants::emptyString, boolean _selectForUpdate = false)
{
    InventItemBarcode inventItemBarcode;
    QueryBuildDataSource qbds;
    QueryBuildRange qbr;
    Query q;
    QueryRun qr;

    q = new Query();
    qbds = q.addDataSource(tableNum(InventItemBarcode));

    qbr = qbds.addRange(fieldNum(InventItemBarcode, ItemBarCode));
    qbr.value(itemBarCode);

    if (barcodeSetupId)
    {
        qbr = qbds.addRange(fieldNum(InventItemBarcode, BarcodeSetupId));
        qbr.value(barcodeSetupId);
    }

    qbds.firstOnly();
    qbds.update(_selectForUpdate);

    qr = new QueryRun(q);
    qr.next();
    inventItemBarcode = qr.get(tableNum(InventItemBarcode));

    return inventItemBarcode;
}
